// C++11: 실제 값은 단 하나의 연속 배열에 저장하세요.
// 각 스택의 예약 용량은 C입니다. 다른 스택의 빈칸은 빌리지 않습니다.
class ThreeStacks {
public:
    explicit ThreeStacks(std::size_t perStack);
    bool Push(int stack, int value);
    bool Pop(int stack, int& out);
    bool Peek(int stack, int& out) const;
    bool Size(int stack, std::size_t& out) const;
};
// 필요한 표준 헤더와 private 멤버를 채우세요.

