#include <array>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <limits>
#include <random>
#include <stdexcept>
#include <vector>

class ThreeStacks {
public:
    // 슬롯은 생성할 때 한 번 확보한다. C=0도 유효한 빈 저장소다.
    explicit ThreeStacks(std::size_t perStack)
        : capacity_(perStack), buffer_(CheckedTotal(perStack), 0),
          sizes_{{0, 0, 0}} {}

    bool Push(int stack, int value) {
        if (!Valid(stack)) return false;
        const std::size_t s = static_cast<std::size_t>(stack);
        if (sizes_[s] == capacity_) return false;
        buffer_[s * capacity_ + sizes_[s]] = value;
        ++sizes_[s];
        return true;
    }

    bool Pop(int stack, int& out) {
        if (!Valid(stack)) return false;
        const std::size_t s = static_cast<std::size_t>(stack);
        if (sizes_[s] == 0) return false;
        out = buffer_[s * capacity_ + sizes_[s] - 1];
        --sizes_[s];
        // 지운 슬롯의 비트는 남아도 논리 원소가 아니다. 다음 Push가 덮어쓴다.
        return true;
    }

    bool Peek(int stack, int& out) const {
        if (!Valid(stack)) return false;
        const std::size_t s = static_cast<std::size_t>(stack);
        if (sizes_[s] == 0) return false;
        out = buffer_[s * capacity_ + sizes_[s] - 1];
        return true;
    }

    bool Size(int stack, std::size_t& out) const {
        if (!Valid(stack)) return false;
        out = sizes_[static_cast<std::size_t>(stack)];
        return true;
    }

private:
    static bool Valid(int stack) { return stack >= 0 && stack < 3; }

    static std::size_t CheckedTotal(std::size_t c) {
        // 곱셈 전에 검사한다. 작은 size_t 구현에서도 오버플로하지 않는다.
        if (c > 100000 || c > std::numeric_limits<std::size_t>::max() / 3)
            throw std::invalid_argument("capacity out of range");
        return 3 * c;
    }

    std::size_t capacity_;
    std::vector<int> buffer_;              // 유일한 가변 길이 값 배열
    std::array<std::size_t, 3> sizes_;       // 크기 메타데이터 세 개
};

// 아래는 테스트용 독립 기준 모델이다. 풀이의 공간 사용과 구분한다.
static std::size_t checks = 0;
static void Check(bool condition) {
    ++checks;
    if (!condition) throw std::runtime_error("test failed");
}

int main() {
    const int low = std::numeric_limits<int>::min();
    const int high = std::numeric_limits<int>::max();
    ThreeStacks t(2);
    int out = 777;
    Check(!t.Pop(0, out) && out == 777);
    Check(t.Push(0, 101));
    Check(t.Push(0, 102));
    Check(!t.Push(0, 103));                 // 다른 스택이 비어도 스택 0은 꽉 참
    Check(t.Push(1, low));
    Check(t.Push(2, high));
    Check(t.Peek(0, out) && out == 102);
    Check(t.Pop(0, out) && out == 102);
    Check(t.Push(0, -7));                   // 반납한 슬롯 재사용
    Check(t.Pop(0, out) && out == -7);
    Check(t.Pop(0, out) && out == 101);
    out = 555;
    Check(!t.Pop(0, out) && out == 555);
    Check(t.Pop(1, out) && out == low);
    Check(t.Pop(2, out) && out == high);
    for (int bad : {-1, 3, low, high}) {
        out = 888;
        std::size_t n = 999;
        Check(!t.Push(bad, 42));
        Check(!t.Pop(bad, out) && out == 888);
        Check(!t.Peek(bad, out) && out == 888);
        Check(!t.Size(bad, n) && n == 999);
    }

    // 음수 크기를 size_t로 바꿔 넘긴 경우도 큰 값으로 거부된다.
    for (std::size_t bad : {std::size_t(100001),
                           std::numeric_limits<std::size_t>::max()}) {
        bool rejected = false;
        try { ThreeStacks invalid(bad); }
        catch (const std::invalid_argument&) { rejected = true; }
        Check(rejected);
    }

    std::mt19937 rng(20261026u);
    std::size_t randomOperations = 0;
    for (std::size_t c : {std::size_t(0), std::size_t(1),
                          std::size_t(2), std::size_t(7)}) {
        ThreeStacks actual(c);
        std::array<std::vector<int>, 3> model;
        for (int step = 0; step < 25000; ++step) {
            const int s = static_cast<int>(rng() % 5) - 1; // -1..3
            const int op = static_cast<int>(rng() % 3);
            const bool valid = s >= 0 && s < 3;
            const int values[] = {low, high, 0, -1, 1, 42, 42};
            const int value = values[rng() % 7];
            int got = 31415;
            bool expected = false;
            int want = got;
            if (op == 0) {
                expected = valid && model[s].size() < c;
                if (expected) model[s].push_back(value);
                Check(actual.Push(s, value) == expected);
            } else {
                expected = valid && !model[s].empty();
                if (expected) {
                    want = model[s].back();
                    if (op == 1) model[s].pop_back();
                }
                const bool ok = op == 1 ? actual.Pop(s, got) : actual.Peek(s, got);
                Check(ok == expected);
                Check(got == want);        // 실패 시 출력 인자 보존도 검사
            }
            for (int k = 0; k < 3; ++k) {
                std::size_t n = 999;
                Check(actual.Size(k, n) && n == model[k].size());
                int top = 27182;
                const bool ok = actual.Peek(k, top);
                Check(ok == !model[k].empty());
                Check(top == (model[k].empty() ? 27182 : model[k].back()));
            }
            ++randomOperations;
        }
    }

    // 최대 크기 검사는 300,000개 슬롯을 만들 수 있는 플랫폼에서 실행한다.
    if (std::numeric_limits<std::size_t>::max() / 3 >= 100000) {
        const std::size_t c = 100000;
        ThreeStacks large(c);
        for (int s = 0; s < 3; ++s) {
            for (std::size_t i = 0; i < c; ++i)
                Check(large.Push(s, static_cast<int>(i % 10000)));
            Check(!large.Push(s, 0));
        }
        for (int s = 2; s >= 0; --s) {
            for (std::size_t i = c; i > 0; --i)
                Check(large.Pop(s, out) && out == static_cast<int>((i - 1) % 10000));
            Check(!large.Pop(s, out));
        }
    }
    std::cout << "PASS checks=" << checks
              << " random_operations=" << randomOperations << '\n';
}
